STUB='''namespace CatalogDesk;

public static class Pricing
{
    public static (DateOnly Start, DateOnly End) PreviousMonth(DateOnly asOf)
        => throw new NotImplementedException();
    public static PriceResult Calculate(decimal basePrice, string productId,
        IEnumerable<OrderLine> orders, DateOnly asOf)
        => throw new NotImplementedException();
    public static (int Total, string Label) StockSummary(IEnumerable<StockItem> stocks)
        => throw new NotImplementedException();
    public static ProductCard CreateCard(Product product, IEnumerable<OrderLine> orders, DateOnly asOf)
        => throw new NotImplementedException();
}
'''
def project_zip(name, starter=False):
    with zipfile.ZipFile(OUT/name,'w',zipfile.ZIP_DEFLATED) as z:
        for p in sorted((ROOT/'app').rglob('*')):
            if not p.is_file() or any(x in p.parts for x in ['bin','obj']):continue
            rel=p.relative_to(ROOT).as_posix()
            if starter and p.name=='Pricing.cs':z.writestr(rel,STUB)
            else:z.write(p,rel)
        z.writestr('README.md','# Каталог и календарная цена\n\nОткрыть app/CatalogDesk.csproj в Windows с .NET SDK 10.\nЗаменить app/Data/catalog.json данными своей области.\n\ndotnet build app/CatalogDesk.csproj\ndotnet run --project app/CatalogDesk.csproj\n\nПорядок работы и проверки: '+SITE+'\n')
project_zip('starter.zip',True);project_zip('reference.zip')
with zipfile.ZipFile(OUT/'data.zip','w',zipfile.ZIP_DEFLATED) as z:
    for p in (ROOT/'data').rglob('*'):
        if p.is_file():z.write(p,p.relative_to(ROOT).as_posix())
with zipfile.ZipFile(OUT/'errors.zip','w',zipfile.ZIP_DEFLATED) as z:
    for p in sorted((ROOT/'data/errors').glob('*.json')):z.write(p,p.relative_to(ROOT).as_posix())
with zipfile.ZipFile(OUT/'tests.zip','w',zipfile.ZIP_DEFLATED) as z:
    for p in sorted((ROOT/'checks').glob('*')):
        if p.is_file():z.write(p,p.relative_to(ROOT).as_posix())
    for folder in ['demo','errors']:
        for p in sorted((ROOT/'data'/folder).glob('*')):z.write(p,p.relative_to(ROOT).as_posix())
    z.writestr('README.md','Распаковать рядом с app собственного проекта. Добавить data/vNN/catalog.json своего варианта. Выполнить из папки с app, checks и data: dotnet run --project checks/PricingChecks.csproj -- .\nПри ошибке сверить первое ожидалось/получено. Исправить модуль и повторить.\n')
for i in range(1,31):
    with zipfile.ZipFile(OUT/f'v{i:02d}.zip','w',zipfile.ZIP_DEFLATED) as z:
        for p in (ROOT/'data'/f'v{i:02d}').iterdir():z.write(p,p.name)

